+  }
+
+  return "development";
+}
+
+function resolveBuildSha(
+  value: string | undefined,
+  mode: RuntimeMode,
+  issues: ConfigurationIssue[],
+): string {
+  const buildSha = value?.trim();
+
+  if (!buildSha) {
+    if (mode === "production") {
+      issues.push("BUILD_SHA_REQUIRED");
+      return "unavailable";
