function runtimeMode(
  value: string | undefined,
  issues: ConfigurationIssue[],
): RuntimeMode {
  if (value === "development" || value === "production" || value === "test") {
    return value;
  }

  issues.push("RUNTIME_MODE_INVALID");
  return "invalid";
}

function resolveBuildSha(
  value: string | undefined,
  mode: RuntimeMode,
  issues: ConfigurationIssue[],
): string {
  const buildSha = value?.trim();

  if (!buildSha) {
    if (mode === "production") {
